ALTER TABLE t
   ADD CONSTRAINT c
      FOREIGN KEY (a, b)
      REFERENCES u (a, b)
      ON DELETE CASCADE
      ON UPDATE SET NULL
      DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE t
   ADD PRIMARY KEY (id),
   ADD COLUMN x integer,
   ADD CONSTRAINT u1
      CHECK (x > 0)
      NOT VALID;
ALTER TABLE t ADD COLUMN y integer;
CREATE TABLE child
   PARTITION OF parent
   FOR VALUES IN (1, 2, 3);
CREATE TABLE c2
   PARTITION OF p
   FOR VALUES FROM (1) TO (10)
   PARTITION BY RANGE (x)
   TABLESPACE ts;
CREATE TABLE c3
   PARTITION OF p
   FOR VALUES WITH (modulus 4, remainder 0);
CREATE TABLE c4 PARTITION OF p DEFAULT;
DROP TABLE IF EXISTS a, b, c CASCADE;
DROP TABLE a;
DROP INDEX CONCURRENTLY IF EXISTS i1, i2;
CREATE DOMAIN d AS integer
   DEFAULT 1
   NOT NULL
   CONSTRAINT pos CHECK (VALUE > 0)
   CHECK (VALUE < 100);
CREATE EXTENSION IF NOT EXISTS pgcrypto
   WITH SCHEMA public
   VERSION '1.3'
   CASCADE;
CREATE EXTENSION hstore;
INSERT INTO t (a, b) VALUES (1, 2) ON CONFLICT (a) DO UPDATE SET b = excluded.b WHERE t.b < 3 RETURNING a;
INSERT INTO t (a) VALUES (1) ON CONFLICT DO NOTHING;
ALTER TABLE t ADD CONSTRAINT k1 FOREIGN KEY (a) REFERENCES u (a) -- a comment keeps this as written
  ON DELETE CASCADE;
